//! A seeded library worth rendering: `seed.sql`, cover PNGs and a markdown vault. No schema:
//! the engine creates it, and INSERTs use explicit column lists so drift fails loudly.

use std::io::Write;
use std::path::{Path, PathBuf};

use rand_chacha::ChaCha8Rng;
use rand_core::{RngCore, SeedableRng};
use serde::Serialize;
use sha2::{Digest, Sha256};

const HEADER: &str = "\
-- GENERATED by `cargo run -p corpus -- gen-devdb`. Do not hand-edit.
--
-- Applied by `make dev-db` to a database the real binary has already created
-- and migrated. Every INSERT lists its columns, so a renamed column fails here
-- by name rather than leaving a silent NULL.
PRAGMA foreign_keys = ON;
BEGIN;
";

/// 2025-01-01 00:00:00 UTC; fixed so timestamps and goldens never move.
const EPOCH: i64 = 1_735_689_600;
const DAY: i64 = 86_400;

const COVER_W: u32 = 240;
const COVER_H: u32 = 360;

pub fn default_out() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .unwrap()
        .parent()
        .unwrap()
        .join("corpus/generated/devdb")
}

/// `cover_path` is a whole path in this schema, so the seed must know where the library lives.
pub fn default_data_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .unwrap()
        .parent()
        .unwrap()
        .join("dev-data")
}

pub fn edge_case_count() -> usize {
    edge_cases().len()
}

#[expect(clippy::too_many_lines)]
pub fn generate(
    root: &Path,
    data_dir: &Path,
    seed: u64,
    ordinary: usize,
) -> std::io::Result<usize> {
    let covers = root.join("covers");
    let vault = root.join("vault");
    std::fs::create_dir_all(&covers)?;
    std::fs::create_dir_all(&vault)?;

    let mut rng = ChaCha8Rng::seed_from_u64(seed);
    let mut books: Vec<Book> = edge_cases();
    let edge_count = books.len();
    for i in 0..ordinary {
        books.push(ordinary_book(&mut rng, edge_count + i + 1));
    }
    // History's books last, so every earlier id is unchanged.
    let history_first = books.len();
    books.extend(HISTORY.iter().map(history_book));
    for (i, b) in books.iter_mut().enumerate() {
        b.id = i as i64 + 1;
    }

    let mut sql = String::from(HEADER);
    let mut notes = Vec::new();
    let mut highlight_id = 0i64;
    let mut reading_id = 0i64;
    let mut reads_of: Vec<(i64, Vec<ReadSpan>)> = Vec::new();

    for b in &books {
        if b.cover {
            let name = format!("dev-{:04}.png", b.id);
            write_cover(&covers.join(&name), b.id)?;
        }
        sql.push_str(&b.insert(data_dir));
        let reads = b.readings(&mut reading_id);
        for r in &reads {
            sql.push_str(&r.sql);
        }
        reads_of.push((
            b.id,
            reads
                .iter()
                .map(|r| (r.id, r.started, r.finished))
                .collect(),
        ));
        for h in b.highlights(&reads, &mut highlight_id, &mut rng) {
            sql.push_str(&h);
        }
        for t in &b.tags {
            sql.push_str(&format!(
                "INSERT INTO book_tags (book_id, tag, source, raw) VALUES ({}, {}, 'goodreads', {});\n",
                b.id,
                q(&t.to_lowercase()),
                q(t)
            ));
        }
        if b.note {
            notes.push(b.clone());
        }
    }

    // Notes last, so their ids are contiguous for the link pass.
    for (i, b) in notes.iter().enumerate() {
        let note_id = i as i64 + 1;
        let slug = format!("{:04}-{}", note_id, slug(&b.title));
        let path = format!("{slug}.md");
        let title = format!("On {}", display_title(&b.title));
        // A dangling link on every third note: `note_links.to_note` is nullable so unresolved targets
        // survive, and both kinds must exist.
        let dangling = note_id % 3 == 0;
        let body = format!(
            "# {title}\n\n\
             A note against *{}*.\n\n\
             It links to [[{}]]{}\n",
            display_title(&b.title),
            if dangling {
                "A Note Nobody Wrote".to_string()
            } else {
                format!("On {}", display_title(&notes[0].title))
            },
            if dangling {
                " — deliberately unresolved."
            } else {
                "."
            }
        );
        std::fs::write(vault.join(&path), &body)?;

        let created = EPOCH + note_id * DAY;
        sql.push_str(&format!(
            "INSERT INTO notes (id, book_id, highlight_id, file_path, title, kind, created_at, last_modified, \
             parts, latest_part_at) \
             VALUES ({note_id}, {}, NULL, {}, {}, 'note', {created}, {created}, 1, {created});\n",
            b.id,
            q(&path),
            q(&title)
        ));
        // No trigger fills `notes_fts`; a note without this row is unfindable by search.
        sql.push_str(&format!(
            "INSERT INTO notes_fts (rowid, title, body) VALUES ({note_id}, {}, {});\n",
            q(&title),
            q(&body)
        ));
        let target = if dangling {
            "A Note Nobody Wrote".to_string()
        } else {
            format!("On {}", display_title(&notes[0].title))
        };
        sql.push_str(&format!(
            "INSERT INTO note_links (from_note, to_note, target_title) VALUES ({note_id}, {}, {});\n",
            if dangling { "NULL".into() } else { "1".to_string() },
            q(&target)
        ));
    }

    let extra = notes_final(
        &mut sql,
        &vault,
        &books,
        &reads_of,
        notes.len() as i64,
        highlight_id,
    )?;
    let history_notes = history(
        &mut sql,
        &vault,
        &books[history_first..],
        reading_id,
        notes.len() as i64 + extra as i64,
        highlight_id + 1,
    )?;

    sql.push_str("COMMIT;\n");
    std::fs::write(root.join("seed.sql"), &sql)?;

    let manifest = Manifest {
        generator_version: GENERATOR_VERSION,
        seed,
        books: books.len(),
        notes: notes.len() + extra + history_notes,
        edge_cases: books[..edge_count]
            .iter()
            .map(|b| EdgeCase {
                id: b.id,
                title: display_title(&b.title),
                what: b.why.to_string(),
            })
            .collect(),
    };
    let mut f = std::fs::File::create(root.join("manifest.json"))?;
    writeln!(
        f,
        "{}",
        serde_json::to_string_pretty(&manifest).expect("manifest is plain data")
    )?;

    Ok(books.len())
}

type ReadSpan = (i64, i64, Option<i64>);

struct SeedNote {
    id: i64,
    book_id: Option<i64>,
    reading_id: Option<i64>,
    kind: &'static str,
    title: String,
    body: String,
    created: i64,
    page: Option<i64>,
    links: Vec<(Option<i64>, String)>,
    parts_at: Vec<i64>,
}

/// Spelled out independently of `notes::PartMarker`: this crate does not link the engine.
fn part_marker(n: i64, at: i64, page: Option<i64>) -> String {
    let stamp = format!(
        "{}T{:02}:{:02}:{:02}Z",
        crate::kostats::ymd(at.div_euclid(DAY)),
        at.rem_euclid(DAY) / 3_600,
        at.rem_euclid(3_600) / 60,
        at.rem_euclid(60)
    );
    match page {
        Some(p) => format!("<!-- part {n} · {stamp} · p. {p} -->"),
        None => format!("<!-- part {n} · {stamp} -->"),
    }
}

#[expect(clippy::too_many_lines)]
fn notes_final(
    sql: &mut String,
    vault: &Path,
    books: &[Book],
    reads_of: &[(i64, Vec<ReadSpan>)],
    base: i64,
    last_highlight: i64,
) -> std::io::Result<usize> {
    let Some(reread) = books.iter().find(|b| b.state == State::Reread) else {
        return Ok(0);
    };
    let reads = &reads_of
        .iter()
        .find(|(id, _)| *id == reread.id)
        .expect("every book's reads are recorded")
        .1;
    let (first, started, _) = reads[0];
    let open = reads.last().copied();
    let book = display_title(&reread.title);

    let maps = base + 4;
    let borders = base + 5;
    let notes = vec![
        SeedNote {
            id: base + 1,
            book_id: Some(reread.id),
            reading_id: Some(first),
            kind: "reflection",
            title: format!("Reflection: {book}"),
            body: format!(
                "What this book is doing to me, kept privately and added to as I go.\n\n\
                 The opening keeps circling one house, and I keep wanting to skip ahead.\n\n\
                 {}\n\n\
                 A week on: the house is the only honest clock in it. It argues with [[Maps That Lie]].\n\n\
                 {}\n\n\
                 Finished. The house outlasts every argument held in it.",
                part_marker(2, started + 9 * DAY, Some(120)),
                part_marker(3, started + 18 * DAY, Some(300)),
            ),
            created: started + 2 * DAY,
            page: Some(40),
            links: vec![(Some(maps), "Maps That Lie".into())],
            parts_at: vec![started + 9 * DAY, started + 18 * DAY],
        },
        SeedNote {
            id: base + 2,
            book_id: Some(reread.id),
            reading_id: Some(first),
            kind: "review",
            title: format!("Review: {book}"),
            body: "Written for other people. Slow, and worth every slow page.".into(),
            created: started + 19 * DAY,
            page: None,
            links: vec![],
            parts_at: vec![],
        },
        SeedNote {
            id: base + 3,
            book_id: Some(reread.id),
            reading_id: None,
            kind: "note",
            title: "Two sittings".into(),
            body: format!(
                "The staircase is described as new for the third time.\n\n{}\n\n\
                 Second sitting: it is new because nobody has climbed it.",
                part_marker(2, started + 5 * DAY, Some(88)),
            ),
            created: started + 3 * DAY,
            page: Some(61),
            links: vec![],
            parts_at: vec![started + 5 * DAY],
        },
        SeedNote {
            id: maps,
            book_id: None,
            reading_id: None,
            kind: "note",
            title: "Maps That Lie".into(),
            body: "# Maps That Lie\n\nEvery map is an argument about where one thing stops.".into(),
            created: EPOCH + 300 * DAY,
            page: None,
            links: vec![],
            parts_at: vec![],
        },
        SeedNote {
            id: borders,
            book_id: None,
            reading_id: None,
            kind: "note",
            title: "Borders are arguments".into(),
            body: "A border is a line somebody won. See [[Maps That Lie]].".into(),
            created: EPOCH + 302 * DAY,
            page: None,
            links: vec![(Some(maps), "Maps That Lie".into())],
            parts_at: vec![],
        },
        SeedNote {
            id: base + 6,
            book_id: None,
            reading_id: None,
            kind: "note",
            title: "Cartographers".into(),
            body: "They drew [[Maps That Lie|what they were paid to]], and \
                   [[Borders are arguments]] follows from it."
                .into(),
            created: EPOCH + 304 * DAY,
            page: None,
            links: vec![
                (Some(maps), "Maps That Lie".into()),
                (Some(borders), "Borders are arguments".into()),
            ],
            parts_at: vec![],
        },
        SeedNote {
            id: base + 7,
            book_id: Some(reread.id),
            reading_id: None,
            kind: "note",
            title: "Atlas".into(),
            body: "Rereading, I kept thinking about maps that lie and the coasts on them. \
                   Someday: [[Coastlines nobody surveyed]]."
                .into(),
            created: EPOCH + 306 * DAY,
            page: None,
            links: vec![(None, "Coastlines nobody surveyed".into())],
            parts_at: vec![],
        },
    ];

    // Edges after every row: a link may name a note seeded after its source (foreign key).
    let mut links = String::new();
    for n in &notes {
        let path = format!("{:04}-{}.md", n.id, slug(&n.title));
        std::fs::write(vault.join(&path), format!("{}\n", n.body))?;
        let markers = &n.parts_at;
        let latest = markers.iter().copied().fold(n.created, i64::max);
        let opt = |v: Option<i64>| v.map(|x| x.to_string()).unwrap_or("NULL".into());
        sql.push_str(&format!(
            "INSERT INTO notes (id, book_id, reading_id, highlight_id, page, file_path, title, kind, \
             created_at, last_modified, parts, latest_part_at) \
             VALUES ({}, {}, {}, NULL, {}, {}, {}, '{}', {}, {}, {}, {latest});\n",
            n.id,
            opt(n.book_id),
            opt(n.reading_id),
            opt(n.page),
            q(&path),
            q(&n.title),
            n.kind,
            n.created,
            latest,
            markers.len() + 1,
        ));
        sql.push_str(&format!(
            "INSERT INTO notes_fts (rowid, title, body) VALUES ({}, {}, {});\n",
            n.id,
            q(&n.title),
            q(&n.body)
        ));
        for (to, target) in &n.links {
            links.push_str(&format!(
                "INSERT INTO note_links (from_note, to_note, target_title) VALUES ({}, {}, {});\n",
                n.id,
                opt(*to),
                q(target)
            ));
        }
    }

    sql.push_str(&links);

    sql.push_str(&format!(
        "INSERT INTO review_ratings (note_id, scale_id, value) \
         SELECT {}, id, 4.0 FROM rating_scales WHERE name = 'default';\n",
        base + 2
    ));

    // A passage typed in by hand: `source = 'user'`, dated inside the open read.
    if let Some((open_id, open_started, _)) = open {
        let at = open_started + 5 * DAY + 4_321;
        let datetime = format!(
            "{} {:02}:{:02}:{:02}.000000000",
            crate::kostats::ymd(at.div_euclid(DAY)),
            at.rem_euclid(DAY) / 3_600,
            at.rem_euclid(3_600) / 60,
            at.rem_euclid(60)
        );
        let text = "Typed in by hand: the house was older than the town.";
        let mut hasher = Sha256::new();
        hasher.update(format!("{}|{datetime}||{text}", reread.id));
        sql.push_str(&format!(
            "INSERT INTO highlights (id, book_id, reading_id, text, chapter, page, ko_datetime, \
             color, origin_note, annotation, source, identity_hash, created_at) VALUES \
             ({}, {}, {open_id}, {}, NULL, 77, {}, NULL, NULL, NULL, 'user', {}, {at});\n",
            last_highlight + 1,
            reread.id,
            q(text),
            q(&datetime),
            q(&hex(&hasher.finalize())),
        ));
    }
    Ok(notes.len())
}

