/// Fixed last day, so the seed does not move with the clock.
const HISTORY_TODAY: (i64, i64, i64) = (2026, 11, 8);

fn history_book(r: &HistoryRead) -> Book {
    Book {
        id: 0,
        title: r.0.to_string(),
        authors: vec![r.1.to_string()],
        page_count: Some(r.2),
        cover: true,
        isbn_13: None,
        series: None,
        subjects: vec!["Fiction".into()],
        tags: vec![],
        state: State::Unread,
        highlights: 0,
        note: false,
        why: "",
    }
}

fn civil((y, m, d): (i64, i64, i64)) -> i64 {
    let y = if m <= 2 { y - 1 } else { y };
    let era = if y >= 0 { y } else { y - 399 } / 400;
    let yoe = y - era * 400;
    let mp = (m + 9) % 12;
    let doy = (153 * mp + 2) / 5 + d - 1;
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    era * 146_097 + doe - 719_468
}

fn pages_on(day: i64, book: i64) -> i64 {
    let h = (day.wrapping_mul(2_654_435_761) ^ book.wrapping_mul(40_503)).rem_euclid(1 << 31);
    if h % 7 < 2 { 0 } else { 6 + h % 31 }
}

/// Measured days are `reading_events` rows (`source = 'koreader'`, `confidence = 'measured'`):
/// origin data that no device-free filler can produce, so the seed writes them.
#[expect(clippy::too_many_lines)]
fn history(
    sql: &mut String,
    vault: &Path,
    books: &[Book],
    mut reading_id: i64,
    mut note_id: i64,
    mut highlight_id: i64,
) -> std::io::Result<usize> {
    let today = civil(HISTORY_TODAY);
    let mut written = 0;
    for (book, r) in books.iter().zip(HISTORY) {
        reading_id += 1;
        let (title, _, pages, started, ended, kind, rating, passages, notes) = *r;
        let start_day = civil(started);
        let start = start_day * DAY + 9 * 3_600;
        let end = ended.map(|e| civil(e) * DAY + 21 * 3_600);
        let (status, finished_at, put_down_at, page) = match kind {
            HistoryKind::Read => ("finished", end, None, Some(pages)),
            HistoryKind::Reading => ("reading", None, None, Some(pages * 2 / 3)),
            // The 2025 one predates the put-down instant: none recorded, and the engine must not invent one.
            HistoryKind::PutDown => (
                "abandoned",
                None,
                if started.0 >= 2026 { end } else { None },
                Some(pages / 3),
            ),
        };
        let opt = |v: Option<i64>| v.map(|x| x.to_string()).unwrap_or("NULL".into());
        let touched = end.unwrap_or(today * DAY);
        sql.push_str(&format!(
            "INSERT INTO readings (id, book_id, started_at, finished_at, status, source, \
             current_page, ko_status, ko_percent, ko_rating, created_at, last_modified, put_down_at) \
             VALUES ({reading_id}, {}, {start}, {}, '{status}', 'koreader', {}, NULL, NULL, NULL, \
             {start}, {touched}, {});\n",
            book.id,
            opt(finished_at),
            opt(page),
            opt(put_down_at),
        ));

        let last_day = end.map_or(today, |e| e.div_euclid(DAY)).min(today);
        let span_days = (last_day - start_day + 1).max(1);
        for day in start_day..=last_day {
            let p = pages_on(day, book.id);
            if p == 0 {
                continue;
            }
            sql.push_str(&format!(
                "INSERT INTO reading_events (book_id, reading_id, day, minutes, pages, source, \
                 confidence, created_at) VALUES ({}, {reading_id}, {}, {}, {p}, 'koreader', \
                 'measured', {});\n",
                book.id,
                q(&crate::kostats::ymd(day)),
                p * 17 / 10,
                day * DAY,
            ));
        }
        for k in 0..passages as i64 {
            highlight_id += 1;
            let at =
                (start_day + (2 * k + 1) * span_days / (2 * passages as i64)) * DAY + 20 * 3_600;
            let datetime = format!(
                "{} {:02}:{:02}:00",
                crate::kostats::ymd(at.div_euclid(DAY)),
                at.rem_euclid(DAY) / 3_600,
                at.rem_euclid(3_600) / 60,
            );
            let text = format!("{}.", PHRASES[(highlight_id as usize) % PHRASES.len()]);
            let mut hasher = Sha256::new();
            hasher.update(format!("{}|{datetime}||{text}", book.id));
            sql.push_str(&format!(
                "INSERT INTO highlights (id, book_id, reading_id, text, chapter, page, ko_datetime, \
                 color, origin_note, annotation, source, identity_hash, created_at) VALUES \
                 ({highlight_id}, {}, {reading_id}, {}, NULL, {}, {}, 'yellow', NULL, NULL, \
                 'koreader', {}, {at});\n",
                book.id,
                q(&text),
                1 + (k * 23) % pages,
                q(&datetime),
                q(&hex(&hasher.finalize())),
            ));
        }
        let mut seeded: Vec<(String, &'static str, Option<i64>, String, i64)> = (0..notes as i64)
            .map(|k| {
                let at = (start_day + (k + 1) * span_days / (notes as i64 + 1)) * DAY + 22 * 3_600;
                (
                    format!("{} — a thought ({})", display_title(title), k + 1),
                    "note",
                    None,
                    format!(
                        "Something in {} I want to keep, the {}th time.",
                        display_title(title),
                        k + 1
                    ),
                    at,
                )
            })
            .collect();
        if rating.is_some() {
            seeded.push((
                format!("Review: {}", display_title(title)),
                "review",
                Some(reading_id),
                "Written for other people.".into(),
                end.unwrap_or(start),
            ));
        }
        for (note_title, kind, read, body, at) in seeded {
            note_id += 1;
            let path = format!("{:04}-{}.md", note_id, slug(&note_title));
            std::fs::write(vault.join(&path), format!("{body}\n"))?;
            sql.push_str(&format!(
                "INSERT INTO notes (id, book_id, reading_id, highlight_id, page, file_path, title, \
                 kind, created_at, last_modified, parts, latest_part_at) VALUES \
                 ({note_id}, {}, {}, NULL, NULL, {}, {}, '{kind}', {at}, {at}, 1, {at});\n",
                book.id,
                opt(read),
                q(&path),
                q(&note_title),
            ));
            sql.push_str(&format!(
                "INSERT INTO notes_fts (rowid, title, body) VALUES ({note_id}, {}, {});\n",
                q(&note_title),
                q(&body)
            ));
            if kind == "review" {
                sql.push_str(&format!(
                    "INSERT INTO review_ratings (note_id, scale_id, value) \
                     SELECT {note_id}, id, {:.1} FROM rating_scales WHERE name = 'default';\n",
                    rating.unwrap_or_default()
                ));
            }
            written += 1;
        }
    }
    Ok(written)
}

pub const GENERATOR_VERSION: u32 = 4;

#[derive(Serialize)]
struct Manifest {
    generator_version: u32,
    seed: u64,
    books: usize,
    notes: usize,
    edge_cases: Vec<EdgeCase>,
}

#[derive(Serialize)]
struct EdgeCase {
    id: i64,
    title: String,
    what: String,
}

#[derive(Clone)]
struct Book {
    id: i64,
    title: String,
    authors: Vec<String>,
    page_count: Option<i64>,
    cover: bool,
    isbn_13: Option<String>,
    series: Option<(String, Option<f64>)>,
    subjects: Vec<String>,
    tags: Vec<String>,
    state: State,
    highlights: usize,
    note: bool,
    why: &'static str,
}

#[derive(Clone, Copy, PartialEq)]
enum State {
    Unread,
    Reading,
    Finished,
    Abandoned,
    Reread,
    /// A status word this build does not know, written straight into `readings.status`, which has
    /// no `CHECK`.
    Unknown,
}

struct Read {
    id: i64,
    started: i64,
    finished: Option<i64>,
    sql: String,
}

impl Book {
    fn insert(&self, data_dir: &Path) -> String {
        let created = EPOCH + self.id * 137;
        let (series, index) = match &self.series {
            Some((s, i)) => (
                q(s),
                i.map(|v| format!("{v}")).unwrap_or_else(|| "NULL".into()),
            ),
            None => ("NULL".to_string(), "NULL".to_string()),
        };
        format!(
            "INSERT INTO books (id, title, sort_title, authors, translators, publisher, \
             publish_year, language, isbn_10, isbn_13, openlibrary_key, googlebooks_id, \
             cover_url, cover_path, page_count, description, first_sentence, \
             subjects, series, series_index, created_at, last_modified) VALUES \
             ({}, {}, NULL, {}, '[]', {}, {}, 'en', NULL, {}, NULL, NULL, NULL, {}, {}, {}, NULL, {}, {series}, {index}, {created}, {created});\n",
            self.id,
            q(&self.title),
            q(&json_array(&self.authors)),
            q("A Publisher"),
            1900 + (self.id % 125),
            self.isbn_13.as_deref().map(q).unwrap_or("NULL".into()),
            // A whole path: `Storage::set_cover` stores `images_dir.join(name)` and nothing joins a prefix
            // back on; a relative one resolves only from a process whose cwd is the data dir.
            if self.cover {
                q(&data_dir
                    .join(format!("database/images/dev-{:04}.png", self.id))
                    .to_string_lossy())
            } else {
                "NULL".into()
            },
            self.page_count
                .map(|p| p.to_string())
                .unwrap_or("NULL".into()),
            q(&format!(
                "A description of {}, long enough to need wrapping in a detail pane but not \
                 long enough to be the only thing on it.",
                display_title(&self.title)
            )),
            q(&json_array(&self.subjects)),
        )
    }

    fn readings(&self, next: &mut i64) -> Vec<Read> {
        let mut out = Vec::new();
        let mut push = |status: &str, started: i64, finished: Option<i64>, page: Option<i64>| {
            *next += 1;
            let sql = format!(
                "INSERT INTO readings (id, book_id, started_at, finished_at, status, source, \
                 current_page, ko_status, ko_percent, ko_rating, created_at, last_modified) VALUES \
                 ({}, {}, {started}, {}, '{status}', 'koreader', {}, NULL, {}, NULL, {started}, {started});\n",
                *next,
                self.id,
                finished.map(|f| f.to_string()).unwrap_or("NULL".into()),
                page.map(|p| p.to_string()).unwrap_or("NULL".into()),
                match (page, self.page_count) {
                    // Absence is not zero: no page count means no percentage, not 0.0.
                    (Some(p), Some(total)) if total > 0 =>
                        format!("{:.4}", p as f64 / total as f64),
                    _ => "NULL".into(),
                }
            );
            out.push(Read {
                id: *next,
                started,
                finished,
                sql,
            });
        };
        let start = EPOCH + self.id * DAY;
        match self.state {
            State::Unread => {}
            State::Reading => push(
                "reading",
                start,
                None,
                Some(self.page_count.unwrap_or(0) / 3),
            ),
            State::Finished => push("finished", start, Some(start + 20 * DAY), self.page_count),
            State::Abandoned => push(
                "abandoned",
                start,
                Some(start + 9 * DAY),
                Some(self.page_count.unwrap_or(0) / 5),
            ),
            State::Reread => {
                push("finished", start, Some(start + 20 * DAY), self.page_count);
                push(
                    "reading",
                    start + 400 * DAY,
                    None,
                    Some(self.page_count.unwrap_or(0) / 2),
                );
            }
            // Open-shaped (no `finished_at`) so it reaches `ReadingState::Other`, not a closed reading.
            State::Unknown => push(
                "paused",
                start,
                None,
                Some(self.page_count.unwrap_or(0) / 4),
            ),
        }
        out
    }

    fn place<'a>(&self, reads: &'a [Read], i: usize) -> (Option<&'a Read>, i64) {
        let n = self.highlights;
        let chunk = n.div_ceil(reads.len().max(1));
        let read = reads.get(i / chunk.max(1));
        // Never on either bound: an instant shared with a neighbouring window is a tie the engine's
        // `ORDER BY` settles. An open reading spreads over its first thirty days.
        let at = match read {
            Some(r) => {
                let span = r.finished.unwrap_or(r.started + 30 * DAY) - r.started;
                let k = (i % chunk) as i64;
                let of = chunk.min(n - (i / chunk) * chunk) as i64;
                r.started + span * (k + 1) / (of + 1)
            }
            None => EPOCH + self.id * DAY + i as i64 * 3_600,
        };
        (read, at)
    }

    /// Each is dated inside a reading's window and attributed to it, as `attribute_highlights`
    /// would, so a re-import does not move it.
    fn highlights(&self, reads: &[Read], next: &mut i64, rng: &mut ChaCha8Rng) -> Vec<String> {
        let n = self.highlights;
        (0..n)
            .map(|i| {
                *next += 1;
                let (read, at) = self.place(reads, i);
                let datetime = format!(
                    "{} {:02}:{:02}:{:02}",
                    crate::kostats::ymd(at.div_euclid(DAY)),
                    at.rem_euclid(DAY) / 3_600,
                    at.rem_euclid(3_600) / 60,
                    at.rem_euclid(60)
                );
                // The passage alone: any suffix would be drawn as if the reader had highlighted it.
                let text = format!("{}.", PHRASES[(rng.next_u32() as usize) % PHRASES.len()]);
                let mut hasher = Sha256::new();
                hasher.update(format!("{}|{datetime}||{text}", self.id));
                // No `highlights_fts` row: triggers on the external-content table fill the index on INSERT.
                format!(
                    "INSERT INTO highlights (id, book_id, reading_id, text, chapter, page, ko_datetime, \
                     color, origin_note, annotation, source, identity_hash, created_at) VALUES \
                     ({}, {}, {}, {}, {}, {}, {}, 'yellow', {}, NULL, 'koreader', {}, {});\n",
                    *next,
                    self.id,
                    read.map(|r| r.id.to_string()).unwrap_or("NULL".into()),
                    q(&text),
                    q(&format!("Chapter {}", 1 + i % 12)),
                    1 + (i as i64 * 17) % self.page_count.unwrap_or(300).max(1),
                    q(&datetime),
                    if i % 4 == 0 {
                        q("What did they mean by this?")
                    } else {
                        "NULL".into()
                    },
                    q(&hex(&hasher.finalize())),
                    EPOCH + *next * 601
                )
            })
            .collect()
    }
}

