#[cfg(test)]
mod tests {
    use super::*;

    const DECLARED: &str = include_str!("../edge-cases.json");

    fn declared() -> Vec<serde_json::Value> {
        let v: serde_json::Value = serde_json::from_str(DECLARED).expect("edge-cases.json parses");
        v["cases"].as_array().expect("a `cases` array").clone()
    }

    fn series_kind(b: &Book) -> &'static str {
        match &b.series {
            None => "none",
            Some((_, Some(_))) => "indexed",
            Some((_, None)) => "unnumbered",
        }
    }

    fn state_name(s: State) -> &'static str {
        match s {
            State::Unread => "unread",
            State::Reading => "reading",
            State::Finished => "finished",
            State::Abandoned => "abandoned",
            State::Reread => "reread",
            State::Unknown => "other",
        }
    }

    #[test]
    fn every_passage_is_dated_inside_the_reading_it_belongs_to() {
        let mut rng = ChaCha8Rng::seed_from_u64(42);
        let mut books = edge_cases();
        let edge = books.len();
        books.extend((0..200).map(|i| ordinary_book(&mut rng, edge + i + 1)));
        let mut next = 0;
        let (mut seen, mut reread) = (0, false);
        for (ix, b) in books.iter_mut().enumerate() {
            b.id = ix as i64 + 1;
            let reads = b.readings(&mut next);
            let holds = |r: &Read, at: i64| at >= r.started && r.finished.is_none_or(|f| at <= f);
            let mut used = std::collections::HashSet::new();
            for i in 0..b.highlights {
                let (read, at) = b.place(&reads, i);
                match read {
                    Some(r) => {
                        seen += 1;
                        used.insert(r.id);
                        assert!(holds(r, at), "{}: highlight {i} outside its read", b.title);
                        assert!(at > r.started && r.finished.is_none_or(|f| at < f));
                        let others = reads.iter().filter(|o| o.id != r.id && holds(o, at));
                        assert_eq!(
                            others.count(),
                            0,
                            "{}: highlight {i} in two windows",
                            b.title
                        );
                    }
                    None => assert!(reads.is_empty()),
                }
            }
            if reads.len() > 1 && b.highlights >= reads.len() {
                assert_eq!(
                    used.len(),
                    reads.len(),
                    "{}: a read with no passage",
                    b.title
                );
                reread = true;
            }
        }
        assert!(seen > 0 && reread);
    }

    #[test]
    fn the_edge_cases_are_the_declared_ones() {
        let cases = declared();
        let ours = edge_cases();
        assert_eq!(
            ours.len(),
            cases.len(),
            "edge-cases.json declares {} cases and gen-devdb builds {}",
            cases.len(),
            ours.len()
        );

        for (i, (book, want)) in ours.iter().zip(cases.iter()).enumerate() {
            // `id` is positional: the hostile set is numbered 1..=n ahead of the ordinary books.
            let id = i as i64 + 1;
            assert_eq!(want["id"].as_i64(), Some(id), "case {i} is out of order");
            let at = format!("case {id} ({})", want["title"].as_str().unwrap_or(""));

            assert_eq!(
                Some(book.title.as_str()),
                want["title"].as_str(),
                "{at}: title"
            );
            let authors: Vec<&str> = want["authors"]
                .as_array()
                .expect("authors is an array")
                .iter()
                .map(|a| a.as_str().expect("an author is a string"))
                .collect();
            assert_eq!(book.authors, authors, "{at}: authors");
            assert_eq!(
                book.page_count,
                want["page_count"].as_i64(),
                "{at}: page_count"
            );
            assert_eq!(Some(book.cover), want["cover"].as_bool(), "{at}: cover");
            assert_eq!(
                Some(state_name(book.state)),
                want["state"].as_str(),
                "{at}: state"
            );
            assert_eq!(
                Some(series_kind(book)),
                want["series"].as_str(),
                "{at}: series"
            );
            assert_eq!(
                Some(book.subjects.len() as u64),
                want["subjects"].as_u64(),
                "{at}: subjects"
            );
        }
    }

    /// Asserted as a partition: the no-cover case is only testable while it is the sole one.
    #[test]
    fn exactly_one_declared_case_has_no_cover() {
        let cases = declared();
        let without: Vec<&str> = cases
            .iter()
            .filter(|c| c["cover"].as_bool() == Some(false))
            .map(|c| c["title"].as_str().expect("a title"))
            .collect();
        assert_eq!(without, ["A Book With No Cover At All"]);
    }

    /// `books.title` is NOT NULL, so the untitled case is the empty string, never null.
    #[test]
    fn the_untitled_case_is_an_empty_string_and_not_an_absence() {
        let untitled = declared()
            .into_iter()
            .filter(|c| c["title"].as_str() == Some(""))
            .count();
        assert_eq!(untitled, 1, "one untitled case, and its title is a string");
    }
}
